client_script:
/* Standalone only: when this form is opened directly (not inside the
   vendor portal's /vendor-embed iframe), it needs its own translate
   widget since there's no portal sidebar around it. When embedded, the
   portal's own translate widget (templates/includes/vendor_portal/
   nav.html) is shown instead -- the sidebar is always visible there, so
   showing this form's widget too would just duplicate the control.
   Tradeoff accepted: the portal's widget lives in the OUTER page and
   can't reach across the iframe boundary to translate this form's own
   fields, so fields go untranslated when embedded -- only the portal
   chrome (nav, page titles) translates in that case. */
if (window.self === window.top) {
const style = document.createElement("style");
style.innerHTML = `
.goog-te-banner-frame { display: none !important; }
body { top: 0 !important; }

/* Use .title's own flex row so the pill shares its padding/edges */
.web-form-head .title {
  display: flex !important;
  align-items: center !important;
  flex-wrap: wrap !important;
  gap: 12px;
}
/* Push the translate pill to the far right of .title, matching
   its right padding instead of .web-form-head's */
#translate-card {
  margin-left: auto;
  background: #ffffff;
  font-family: inherit;
  flex-shrink: 0;
}
#translate-card svg {
  margin-top: 10px;
  flex-shrink: 0;
  color: #5f6b7a;
}
#translate-card span {
  margin-top: 10px;
  font-size: 12px;
  color: #5f6b7a;
  white-space: nowrap;
}
#google_translate_element .goog-te-gadget {
  font-family: inherit !important;
  font-size: 0 !important;
}
#google_translate_element .goog-te-gadget-simple {
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
}
.goog-te-combo {
  font-family: inherit !important;
  font-size: 12px !important;
  color: #1c1f24 !important;
  background: #f7f8fa !important;
  border: 1px solid #dfe2e6 !important;
  border-radius: 6px !important;
  padding: 3px 6px !important;
  cursor: pointer;
  outline: none;
}
.goog-te-combo:hover {
  border-color: #b9bec5 !important;
}
.goog-te-gadget img { display: none !important; }
.goog-te-gadget > span > a { display: none !important; }
.goog-te-gadget .goog-te-gadget-icon { display: none !important; }
`;
document.head.appendChild(style);

if (!document.getElementById("translate-card")) {
const card = document.createElement("div");
card.id = "translate-card";
card.innerHTML = `
  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8">
    <circle cx="12" cy="12" r="9"/>
    <path d="M3 12h18M12 3c2.5 2.7 4 6 4 9s-1.5 6.3-4 9c-2.5-2.7-4-6-4-9s1.5-6.3 4-9z"/>
  </svg>
  <span>Translate:</span>
  <div id="google_translate_element"></div>
`;
// Anchor inside .title so it inherits the same right padding/edge
// as "Vendor Form" + "Not Saved" and the rest of the form content.
const anchor = document.querySelector(".web-form-head .title") || document.querySelector(".web-form-head") || document.body;
anchor.appendChild(card);
}

window.googleTranslateElementInit = () => {
new google.translate.TranslateElement(
  { pageLanguage: "en", autoDisplay: false },
  "google_translate_element"
);
};
if (!document.getElementById("google-translate-script")) {
const script = document.createElement("script");
script.id = "google-translate-script";
script.src = "https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit";
document.body.appendChild(script);
}

/* The CSS rule above (.goog-te-banner-frame { display: none }) doesn't
   reliably win -- Google's script re-applies its own inline styles to
   that iframe after insertion, and re-pushes body down, whenever a
   language is picked. A MutationObserver catches and undoes that every
   time instead of relying on CSS to hold. */
(function () {
	function hideTranslateBanner() {
		document.querySelectorAll(".goog-te-banner-frame").forEach(function (el) {
			el.style.display = "none";
		});
		if (document.body && document.body.style.top && document.body.style.top !== "0px") {
			document.body.style.top = "0px";
		}
	}
	hideTranslateBanner();
	new MutationObserver(hideTranslateBanner).observe(document.documentElement, {
		childList: true,
		subtree: true,
		attributes: true,
		attributeFilter: ["style"],
	});
})();
}

/* When this form is embedded inside the vendor portal's iframe (not
   opened directly), widen it to fill that iframe instead of staying
   capped at its own standalone reading width. Runs natively inside this
   page's own document -- no cross-document injection or load-event
   timing to get wrong, unlike trying to reach in from the parent page
   (which is exactly what made the first attempt at this unreliable). */
if (window.self !== window.top) {
	var vpEmbedWidthStyle = document.createElement("style");
	vpEmbedWidthStyle.innerHTML = ""
		+ ".web-form-container { max-width: none !important; width: 100% !important; }"
		+ " main.container { max-width: none !important; width: 100% !important; padding-left: 0 !important; padding-right: 0 !important; margin-left: 0 !important; margin-right: 0 !important; }";
	document.head.appendChild(vpEmbedWidthStyle);
}

/* Company is read-only on this form -- the built-in query-param prefill
   (WebForm.set_default_values(), which merges every URL param straight
   into field values by exact fieldname match, same mechanism that
   already prefills email_id) doesn't reliably show up for this
   particular field once rendered read-only, so it's set explicitly here
   instead: both through the normal model API (so it's the real
   submitted value) and directly on the input's displayed value (so it's
   guaranteed visible regardless of whatever is behind that). Retries
   briefly since fields_dict may not be populated yet at the instant this
   runs. */
(function () {
	var params = new URLSearchParams(window.location.search);
	var company = params.get("custom_company");
	if (!company) return;

	function applyCompany() {
		var wf = frappe.web_form;
		if (!wf || !wf.fields_dict || !wf.fields_dict.custom_company) return false;
		wf.set_value("custom_company", company);
		var control = wf.fields_dict.custom_company;
		if (control.$input) {
			control.$input.val(company);
		}
		return true;
	}

	if (!applyCompany()) {
		var attempts = 0;
		var poll = setInterval(function () {
			attempts += 1;
			if (applyCompany() || attempts > 40) {
				clearInterval(poll);
			}
		}, 50);
	}
})();

/* Freeze the screen while the form is actually saving, with a clear
   message, until the save genuinely finishes (success or failure).

   NOT using frappe.dom.freeze() -- its element only ever gets attached
   via .appendTo("#body"), and #body is a Desk-shell-only id (frappe/www/
   desk.html) that plain website pages, this one included, never render.
   With zero elements matching "#body", jQuery's appendTo() is a silent
   no-op: freeze() still runs start to finish with no error, but the
   overlay it builds is never actually inserted into the page -- looked
   for it directly in this page's own rendered HTML and confirmed there's
   no "#body" anywhere, nor any script that creates one. So this builds
   its own overlay instead, attached to the real document.body (always
   present, unlike "#body"), fully self-contained rather than depending
   on Desk-only CSS or Bootstrap's .modal-backdrop being loaded here.

   Listens on the Submit button's own click (delegated via document, so
   it doesn't matter whether the button exists yet when this runs) rather
   than the form's "submit" event -- core's own submit handler returns
   false from save(), which jQuery turns into preventDefault() +
   stopPropagation() on its own event object, and that interaction with a
   second, independently-attached native "submit" listener on the same
   element isn't something worth relying on being safe. A click on the
   button is a separate, earlier event nothing here touches, so it always
   fires regardless of what the form's own submit handling does.

   There's no public "save finished" hook for both the success AND
   failure paths (frappe.web_form.events only fires after_save on
   success), so this watches window.saving instead -- the same plain flag
   core flips true right before the request and back to false in
   frappe.call's own `always` handler regardless of outcome (it's
   literally what core uses to block double-submits). */
function vpShowSaveFreeze(message) {
	if (document.getElementById("vp-save-freeze")) return;
	var overlay = document.createElement("div");
	overlay.id = "vp-save-freeze";
	overlay.innerHTML =
		'<div class="vp-save-freeze-box">'
		+ '<div class="vp-save-freeze-spinner"></div>'
		+ "<p>" + message + "</p>"
		+ "</div>";
	document.body.appendChild(overlay);
}
function vpHideSaveFreeze() {
	var overlay = document.getElementById("vp-save-freeze");
	if (overlay) overlay.remove();
}

document.addEventListener("click", function (e) {
	var btn = e.target.closest(".web-form-actions .submit-btn");
	if (!btn) return;

	// Freeze immediately for instant feedback on click; if core's own
	// validation rejects the submit synchronously (window.saving never
	// gets set), un-freeze right away instead of leaving it stuck up
	// over a save that never actually started.
	vpShowSaveFreeze("Saving your details. Please do not close or refresh this page...");

	setTimeout(function () {
		if (!window.saving) {
			vpHideSaveFreeze();
			return;
		}
		var check = setInterval(function () {
			if (!window.saving) {
				clearInterval(check);
				vpHideSaveFreeze();
			}
		}, 100);
	}, 50);
});

custom_css:
:root {
	--vp-accent: #4f46e5;
	--vp-accent-soft: rgba(79, 70, 229, 0.1);
}

body {
	background-color: var(--bg-light-gray);
}

.web-form-container {
	max-width: 860px;
}

/* Shrink the fixed-height spacer core inserts above the header when
   there's no breadcrumb/banner -- tightens the gap before the card. */
.web-form-container > div[style*="height: 3rem"] {
	height: 1rem !important;
}

/* ---------- Header and form body render as ONE unbroken surface.
   .web-form-header and .web-form are sibling elements in the DOM (not
   nested), so to look like a single form: identical background, no
   border or shadow on either side of the join, radius only on the true
   outer corners, zero margin between them. ---------- */
.web-form-container .web-form-header {
	background-color: var(--bg-color) !important;
	border: 1px solid var(--border-color) !important;
	border-bottom: none !important;
	border-radius: 16px 16px 0 0 !important;
	margin-bottom: 0 !important;
	padding: 0.85rem 1.75rem !important;
}

.web-form-container .web-form-head {
	min-height: 0 !important;
}

.web-form-container .web-form-head .title {
	align-items: center !important;
	gap: 0.6rem !important;
	margin: 0 !important;
}

.web-form-container .web-form-head .title h1,
.web-form-container .web-form-title h1 {
	font-size: 0.95rem !important;
	line-height: 1.3 !important;
	font-weight: 700 !important;
	color: var(--text-color) !important;
	letter-spacing: -0.01em !important;
	margin: 0 !important;
}

.web-form-container .web-form-head .title p {
	color: var(--text-light) !important;
	font-size: 0.75rem !important;
	margin: 0 !important;
}

.web-form-container .indicator-pill {
	display: none !important;
}

.web-form-container .web-form-head .web-form-actions {
	margin-left: auto !important;
}

.web-form-container .web-form-head .edit-button.btn,
.web-form-container .web-form-head .print-btn.btn {
	font-size: 0.8rem !important;
	padding: 0.3rem 0.8rem !important;
	border-radius: 8px !important;
}

.web-form-container #translate-card {
	transform: scale(0.75) !important;
	transform-origin: right center !important;
	opacity: 0.8 !important;
}

.web-form-introduction {
	color: var(--text-light) !important;
	font-size: 0.8rem !important;
	margin-top: 4px !important;
}

/* Form body: bottom half of the same surface, directly against the
   header above -- no border-top, no top radius, no shadow (a shadow on
   just this element would draw a visible line right at the join). */
.web-form {
	background-color: var(--bg-color) !important;
	border: 1px solid var(--border-color) !important;
	border-top: none !important;
	border-radius: 0 0 16px 16px !important;
	box-shadow: none !important;
	overflow: hidden !important;
	margin-top: 0 !important;
}

.web-form-body {
	padding: 0 1rem !important;
}

.web-form-footer {
	background-color: var(--bg-color) !important;
	border-top: 1px solid var(--border-color) !important;
	padding: 0.75rem 1.5rem !important;
}

/* ---------- Sections flow directly one after another -- no open gap,
   just the heading + its underline to mark where one ends and the next
   begins. ---------- */
.form-section {
	padding-top: 0.5rem !important;
	padding-bottom: 0.5rem !important;
}

.form-section .section-head,
.form-section .section-head-label {
	font-size: 0.9rem !important;
	font-weight: 700 !important;
	color: var(--text-color) !important;
	padding-bottom: 0.4rem !important;
	border-bottom: 1px solid var(--border-color) !important;
	margin-bottom: 0.6rem !important;
}

.form-section .form-section-description {
	color: var(--text-light) !important;
	font-size: 0.78rem !important;
	margin-bottom: 0.5rem !important;
}

.form-column {
	margin-bottom: 0.6rem !important;
}

/* ---------- Field labels ---------- */
.control-label {
	font-size: 0.78rem !important;
	font-weight: 500 !important;
	color: var(--text-light) !important;
	margin-bottom: 0.25rem !important;
}

/* ---------- Inputs, selects, textareas ---------- */
.web-form input.form-control,
.web-form textarea.form-control,
.web-form .form-control {
	border: 1px solid var(--border-color) !important;
	border-radius: 8px !important;
	padding: 0.4rem 0.7rem !important;
	font-size: 0.85rem !important;
	line-height: 1.4 !important;
	background-color: var(--bg-color) !important;
	color: var(--text-color) !important;
	box-shadow: none !important;
	min-height: 2.1rem !important;
	transition: border-color 0.15s ease, box-shadow 0.15s ease !important;
}

/* Select needs its own rule (not lumped in with input/textarea above) --
   giving it identical padding to text inputs clips the option text at the
   bottom in most browsers once the native appearance is touched at all,
   so it gets an explicit height/line-height and a CSS-only arrow instead
   of relying on the browser's inconsistent native rendering. */
.web-form select.form-control {
	border: 1px solid var(--border-color) !important;
	border-radius: 8px !important;
	background-color: var(--bg-color) !important;
	color: var(--text-color) !important;
	box-shadow: none !important;
	font-size: 0.85rem !important;
	line-height: 1.4 !important;
	height: 2.1rem !important;
	padding: 0.3rem 1.9rem 0.3rem 0.7rem !important;
	-webkit-appearance: none !important;
	-moz-appearance: none !important;
	appearance: none !important;
	background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%238d99a6' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3e%3cpolyline points='6 9 12 15 18 9'%3e%3c/polyline%3e%3c/svg%3e") !important;
	background-repeat: no-repeat !important;
	background-position: right 0.6rem center !important;
	background-size: 16px !important;
}

.web-form input.form-control:focus,
.web-form select.form-control:focus,
.web-form textarea.form-control:focus {
	border-color: var(--vp-accent) !important;
	box-shadow: 0 0 0 3px var(--vp-accent-soft) !important;
	outline: none !important;
}

.web-form input.form-control:disabled,
.web-form select.form-control:disabled,
.web-form .form-control[readonly] {
	background-color: var(--bg-light-gray) !important;
	color: var(--text-light) !important;
}

/* ---------- Checkboxes ---------- */
.web-form .checkbox input[type="checkbox"],
.web-form input[type="checkbox"] {
	width: 16px !important;
	height: 16px !important;
	accent-color: var(--vp-accent) !important;
	cursor: pointer !important;
}

.web-form .checkbox label,
.web-form .frappe-control[data-fieldtype="Check"] label {
	font-size: var(--text-sm) !important;
	color: var(--text-color) !important;
	cursor: pointer !important;
}

/* ---------- Buttons ---------- */
.web-form-actions .btn {
	border-radius: 8px !important;
	font-size: var(--text-sm) !important;
	font-weight: 600 !important;
	padding: 0.5rem 1.1rem !important;
}

.web-form-actions .btn-primary,
.web-form-actions .submit-btn {
	background-color: var(--vp-accent) !important;
	border-color: var(--vp-accent) !important;
}

.web-form-actions .btn-primary:hover,
.web-form-actions .submit-btn:hover {
	background-color: #4338ca !important;
	border-color: #4338ca !important;
}

.web-form-actions .btn-default,
.web-form-actions .discard-btn {
	background-color: var(--bg-light-gray) !important;
	border-color: var(--border-color) !important;
	color: var(--text-color) !important;
}

/* ---------- Attach fields ---------- */
.web-form .btn-attach,
.web-form .attach-preview {
	border-radius: 8px !important;
}

/* ---------- Success page ---------- */
.success-page .success-icon {
	color: #10a34a !important;
	width: 48px !important;
	height: 48px !important;
}

.success-page .success-title {
	font-size: 1.4rem !important;
	font-weight: 700 !important;
	color: var(--text-color) !important;
}

.success-page .success-message {
	color: var(--text-light) !important;
}

/* ---------- Attachments / comments panels ---------- */
.attachments,
.comments {
	background-color: var(--bg-color) !important;
	border: 1px solid var(--border-color) !important;
	border-radius: 14px !important;
	padding: 1.25rem 1.5rem !important;
	margin-top: 1.5rem !important;
}

/* The "saving" overlay built in client_script (vpShowSaveFreeze) --
   deliberately its own element (#vp-save-freeze), not frappe.dom's
   #freeze: that only ever attaches via .appendTo("#body"), and #body is
   a Desk-shell-only id (frappe/www/desk.html) this website page never
   renders, so frappe.dom.freeze() runs with no error but its overlay is
   never actually inserted into the page at all -- confirmed directly in
   this page's own rendered HTML, no "#body" anywhere. Self-contained
   here (not assuming Bootstrap's .modal-backdrop is loaded either) so it
   actually renders regardless of what else is on the page. */
#vp-save-freeze {
	position: fixed !important;
	top: 0 !important;
	right: 0 !important;
	bottom: 0 !important;
	left: 0 !important;
	z-index: 999999 !important;
	background-color: rgba(0, 0, 0, 0.6) !important;
	display: flex !important;
	align-items: center !important;
	justify-content: center !important;
	padding: 2rem !important;
}
.vp-save-freeze-box {
	background: #fff !important;
	color: #1c1f24 !important;
	padding: 1.75rem 2.25rem !important;
	border-radius: 10px !important;
	max-width: 90vw !important;
	text-align: center !important;
	box-shadow: 0 10px 40px rgba(0, 0, 0, 0.25) !important;
	display: flex !important;
	flex-direction: column !important;
	align-items: center !important;
	gap: 0.75rem !important;
}
.vp-save-freeze-spinner {
	width: 28px !important;
	height: 28px !important;
	border: 3px solid #e5e7eb !important;
	border-top-color: var(--vp-accent, #4f46e5) !important;
	border-radius: 50% !important;
	animation: vp-save-freeze-spin 0.8s linear infinite !important;
}
@keyframes vp-save-freeze-spin {
	to {
		transform: rotate(360deg);
	}
}
.vp-save-freeze-box p {
	margin: 0 !important;
	font-size: 1rem !important;
	font-weight: 600 !important;
}

/* ---------- Make Web Form text bold ---------- */

.web-form-container,
.web-form-container .web-form,
.web-form-container .web-form-header,
.web-form-container .web-form-body,
.web-form-container .web-form-footer {
	font-weight: 700 !important;
}

/* Field labels */
.web-form-container .control-label {
	font-weight: 700 !important;
}

/* Input / Select / Textarea text */
.web-form-container input.form-control,
.web-form-container select.form-control,
.web-form-container textarea.form-control {
	font-weight: 700 !important;
}

/* Checkbox labels */
.web-form-container .checkbox label,
.web-form-container .frappe-control[data-fieldtype="Check"] label {
	font-weight: 700 !important;
}

/* Section headings */
.web-form-container .section-head,
.web-form-container .section-head-label {
	font-weight: 700 !important;
}

/* Section descriptions */
.web-form-container .form-section-description {
	font-weight: 600 !important;
}

/* Buttons */
.web-form-container .btn {
	font-weight: 700 !important;
}
